<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { ArrowUpRight, ArrowLeftRight, Clock3, Info, ChevronLeft, ChevronRight, LoaderCircle } from 'lucide-vue-next'
import PageHeading from '../components/PageHeading.vue'
import StatePanel from '../components/StatePanel.vue'
import AppModal from '../components/AppModal.vue'
import { toast } from '../components/ToastStack.vue'
import { api, allPages, query, encode, meetingText, type Page, type Enrollment, type Waitlist, type Section } from '../lib/api'
import { useWorkspace } from '../stores/workspace'
import { useAsync } from '../lib/useAsync'
import { formatTime } from '../lib/format'

const workspace = useWorkspace(), { loading, error, run } = useAsync()
const tab = ref('enrolled'), enrollments = ref<Enrollment[]>([]), waitlists = ref<Waitlist[]>([]), page = ref(0), total = ref(0), size = 15
const operation = ref<'withdraw' | 'swap' | 'cancel' | ''>(''), selected = ref<Enrollment | Waitlist>(), targets = ref<Section[]>([]), targetId = ref(''), busy = ref(false), modalError = ref(''), targetsLoading = ref(false)
const pages = computed(() => Math.max(1, Math.ceil(total.value / size)))
const stateText = (state: string) => ({ WAITING: '候补等待中', ENROLLED: '已递补选中', CANCELLED: '已取消', SKIPPED: '资格变化未递补', EXPIRED: '轮次已结束', WITHDRAWN: '已退课', ACTIVE: '已选中' }[state] || state)
async function load(reset = false) { if (reset) page.value = 0; await run(() => api<Page<Enrollment | Waitlist>>((tab.value === 'enrolled' ? '/student/enrollments' : '/student/waitlist') + query({ termId: workspace.termId, page: page.value, size })), result => { total.value = result.total; if (tab.value === 'enrolled') enrollments.value = result.items as Enrollment[]; else waitlists.value = result.items as Waitlist[] }) }
watch([() => workspace.termId, tab], () => load(true), { immediate: true })
async function open(kind: 'withdraw' | 'swap' | 'cancel', row: Enrollment | Waitlist) { operation.value = kind; selected.value = row; targetId.value = ''; modalError.value = ''; if (kind === 'swap') { targetsLoading.value = true; try { targets.value = (await allPages<Section>('/catalog' + query({ termId: workspace.termId }))).filter(item => item.id !== row.sectionId) } catch (e) { modalError.value = e instanceof Error ? e.message : '目标教学班读取失败' } finally { targetsLoading.value = false } } }
async function submit() { if (!selected.value) return; busy.value = true; modalError.value = ''; try { if (operation.value === 'withdraw') { const result = await api<{ promotionPending: boolean }>('/student/enrollments/' + encode(selected.value.sectionId), { method: 'DELETE', idempotent: true }); toast(result.promotionPending ? '已退课，空余名额正在按候补顺序递补。' : '已成功退课，课表与已选学分同步更新。') } else if (operation.value === 'cancel') { await api('/student/waitlist/' + encode(selected.value.id), { method: 'DELETE', idempotent: true }); toast('已取消这次候补申请。') } else { await api('/student/swaps', { method: 'POST', body: { sourceSectionId: selected.value.sectionId, targetSectionId: targetId.value }, idempotent: true }); toast('换课成功。原课程已退选，新课程已加入课表。') } operation.value = ''; await load() } catch (e) { modalError.value = e instanceof Error ? e.message : '提交失败' } finally { busy.value = false } }
function paginate(delta: number) { page.value += delta; void load() }
</script>
<template><PageHeading eyebrow="YOUR LEARNING, IN ONE PLACE" title="我的课程" description="管理已选课程，查看候补进度，为每一次选择留出清晰的空间。"><select v-model="workspace.termId" class="select-control" aria-label="选择学期"><option v-for="term in workspace.terms" :key="term.id" :value="term.id">{{ term.name }}</option></select><RouterLink to="/student/catalog" class="button">继续选课<ArrowUpRight :size="14"/></RouterLink></PageHeading><div class="tabs" role="tablist" aria-label="课程类型"><button role="tab" :aria-selected="tab === 'enrolled'" :class="{ active: tab === 'enrolled' }" @click="tab = 'enrolled'">已选课程</button><button role="tab" :aria-selected="tab === 'waiting'" :class="{ active: tab === 'waiting' }" @click="tab = 'waiting'">候补记录</button></div><div class="notice-banner"><Info :size="16"/><span>{{ tab === 'enrolled' ? '需要调整安排？换课会同时校验新课程；如果新课程不满足条件，原有选课会完整保留。' : '候补按入队顺序处理，出现空位后会再次检查时间、学分与先修条件。请留意消息中心。' }}</span></div><section class="card"><div class="card-header"><div><h2>{{ tab === 'enrolled' ? '已选课程' : '候补申请记录' }}</h2><p>{{ workspace.currentTerm?.name }} · 共 {{ total }} 条记录</p></div><button class="text-button" :disabled="loading" @click="load()">刷新记录 ↻</button></div><StatePanel v-if="loading" loading/><StatePanel v-else-if="error" :error="error" @retry="load()"/><StatePanel v-else-if="!total" :title="tab === 'enrolled' ? '还没有选中的课程' : '还没有候补申请'" :description="tab === 'enrolled' ? '去选课中心看看，为新学期安排第一门心仪的课程。' : '名额已满时，可以在课程详情中申请候补。'"/><div v-else class="table-wrap"><table v-if="tab === 'enrolled'"><caption class="sr-only">当前学期已选课程</caption><thead><tr><th>课程 / 教学班</th><th>教师 / 学分</th><th>上课安排</th><th>成绩状态</th><th>课程管理</th></tr></thead><tbody><tr v-for="item in enrollments" :key="item.id"><td><strong>{{ item.courseTitle }}</strong><small>{{ item.sectionId }}</small></td><td>{{ item.teacherName }}<small>{{ item.credits }} 学分</small></td><td><small v-for="(meeting, i) in item.meetings" :key="i">{{ meetingText(meeting) }}</small></td><td><span class="tag" :class="{ 'tag-neutral': item.grade == null }">{{ item.grade != null ? '成绩已发布' : '成绩未发布' }}</span><small v-if="item.state === 'WITHDRAWN'">已退课</small></td><td><div v-if="item.state !== 'WITHDRAWN'" class="row-actions"><button class="text-button" @click="open('swap', item)"><ArrowLeftRight :size="11"/>换课</button><button class="text-button text-red" @click="open('withdraw', item)">退课</button></div><span v-else class="muted">已结束</span></td></tr></tbody></table><table v-else><caption class="sr-only">候补申请</caption><thead><tr><th>课程 / 教学班</th><th>排队进度</th><th>状态</th><th>申请时间</th><th>操作</th></tr></thead><tbody><tr v-for="item in waitlists" :key="item.id"><td><strong>{{ item.courseTitle }}</strong><small>{{ item.sectionId }}</small></td><td><span v-if="item.state === 'WAITING'" class="tag tag-gold"><Clock3 :size="10"/>当前第 {{ item.position }} 位</span><span v-else class="muted">已处理</span><small>队列号 {{ item.queueNo }}</small></td><td><span class="tag" :class="{ 'tag-neutral': item.state !== 'WAITING' && item.state !== 'ENROLLED', 'tag-gold': item.state === 'WAITING' }">{{ stateText(item.state) }}</span><small v-if="item.reason">{{ item.reason }}</small></td><td>{{ formatTime(item.createdAt) }}</td><td><button v-if="item.state === 'WAITING'" class="text-button text-red" @click="open('cancel', item)">取消候补</button><span v-else class="muted">无需操作</span></td></tr></tbody></table></div><div v-if="total" class="card-footer"><span>第 {{ page + 1 }} / {{ pages }} 页</span><div class="pagination"><button aria-label="上一页" :disabled="page === 0 || loading" @click="paginate(-1)"><ChevronLeft :size="14"/></button><button aria-label="下一页" :disabled="page + 1 >= pages || loading" @click="paginate(1)"><ChevronRight :size="14"/></button></div></div></section><AppModal :open="!!operation" :title="operation === 'swap' ? '调整我的课程' : operation === 'withdraw' ? '确认退课' : '取消候补申请'" :busy="busy" @close="operation = ''"><div v-if="modalError" class="error-inline" role="alert">{{ modalError }}</div><template v-if="selected"><p class="modal-description">{{ selected.courseTitle }} · {{ selected.sectionId }}</p><template v-if="operation === 'swap'"><div class="notice-banner"><Info :size="15"/><span>换课作为一个完整操作提交。新课程校验失败时，原课程保持不变，不会先退后选。</span></div><StatePanel v-if="targetsLoading" loading/><label v-else class="field">选择要换入的教学班<select v-model="targetId" required><option disabled value="">请选择目标教学班</option><option v-for="item in targets" :key="item.id" :value="item.id">{{ item.courseTitle }} · {{ item.id }} · {{ item.teacherName }}（{{ item.enrolledCount }}/{{ item.capacity }}）</option></select><small>提交时会重新检查时间冲突、学分、先修条件和剩余名额。</small></label><div v-if="targetId" class="detail-summary mt-20"><p v-for="(meeting, i) in targets.find(item => item.id === targetId)?.meetings || []" :key="i">{{ meetingText(meeting) }}</p></div></template><p v-else class="preview-alert">{{ operation === 'withdraw' ? '确认后将退选该教学班，课表与已选学分同步更新。释放出的名额可能会立即递补给候补同学。' : '取消后将退出本次排队；再次申请候补时，会以新的队列号重新排队。' }}</p></template><template #footer><button class="button button-secondary" :disabled="busy" @click="operation = ''">再想一想</button><button class="button" :class="{ 'button-danger': operation !== 'swap' }" :disabled="busy || targetsLoading || (operation === 'swap' && !targetId)" @click="submit"><LoaderCircle v-if="busy" :size="14" class="spin"/>{{ busy ? '正在处理…' : operation === 'swap' ? '确认换课' : operation === 'withdraw' ? '确认退课' : '确认取消' }}</button></template></AppModal></template>
